7	/// Speech-to-text engine that backs a model. Each engine has its own
8	/// inference path in [`crate::handlers::whisper::transcribe_audio`].
9	#[derive(Clone, Copy, PartialEq, Eq)]
10	pub enum Engine {
11	    Whisper,
12	    Parakeet,
