                tauri::RunEvent::ExitRequested { code, .. } => {
                    log::warn!(target: "runtime", "exit_requested code={code:?}");
                }
                tauri::RunEvent::Exit => {
                    log::warn!(target: "runtime", "exit");
                }
                _ => {}
            }
        });
